// ===== js/poki.js =====
// poki.js - Poki SDK integration (global-script version of the overbite module).
//
// The SDK itself is loaded as a <script> in index.html (window.PokiSDK). If it is
// absent (local/offline dev) every call degrades to a safe no-op, so the game runs
// identically with or without Poki.
//
// FLAGS:
//   enabled    - master switch for ALL Poki calls (false = pure offline mode).
//   adsEnabled - gates ONLY the ad breaks. Stays false for dev/testing; the release
//                build turns it on (main.js: adsEnabled = !window.DEV_TOOLS).
(function (global) {
  "use strict";

  const Poki = {
    enabled: true,
    adsEnabled: false,
    initialized: false,
    isPlaying: false,
    audioSink: null,        // set by main.js; muted for the duration of an ad break

    async init() {
      if (!this.enabled || typeof PokiSDK === "undefined") {
        console.log("Poki SDK not available - running in offline mode");
        this.initialized = false;
        return true;
      }
      try {
        await PokiSDK.init();
        this.initialized = true;
        this.initVisibilityHandler();
        console.log("Poki SDK initialized");
      } catch (e) {
        console.log("Poki SDK init failed, continuing anyway:", e);
        this.initialized = false;
      }
      return true;
    },

    // Call once all assets are loaded and the game is ready to play.
    gameLoadingFinished() {
      if (!this.initialized) return;
      try { PokiSDK.gameLoadingFinished(); } catch (e) { console.warn("Poki gameLoadingFinished error:", e); }
    },

    // Player entered active gameplay (first input). No double-fire.
    gameplayStart() {
      if (this.isPlaying) return;
      this.isPlaying = true;
      if (!this.initialized) return;
      try { PokiSDK.gameplayStart(); } catch (e) { console.warn("Poki gameplayStart error:", e); }
    },

    // Player left active gameplay (end screen, pause, tab hidden). No double-fire.
    gameplayStop() {
      if (!this.isPlaying) return;
      this.isPlaying = false;
      if (!this.initialized) return;
      try { PokiSDK.gameplayStop(); } catch (e) { console.warn("Poki gameplayStop error:", e); }
    },

    // Pause/resume gameplay tracking when the tab is hidden/shown (covers mobile
    // interruptions where there is no ESC key).
    initVisibilityHandler() {
      document.addEventListener("visibilitychange", () => {
        if (!this.initialized || !this.isPlaying) return;
        try {
          if (document.hidden) PokiSDK.gameplayStop();
          else PokiSDK.gameplayStart();
        } catch (e) { }
      });
    },

    // Interstitial at a natural break (between runs). Resolves when done/skipped/
    // failed. No-op (instant resolve) while adsEnabled is false.
    async commercialBreak() {
      if (!this.adsEnabled || !this.initialized) return;
      try {
        if (this.isPlaying) { PokiSDK.gameplayStop(); this.isPlaying = false; }
        if (this.audioSink) this.audioSink.setAdMuted(true);
        await PokiSDK.commercialBreak();
      } catch (e) { console.warn("Poki commercialBreak error:", e); }
      finally { if (this.audioSink) this.audioSink.setAdMuted(false); this.reclaimFocus(); }
    },

    // After an ad (its iframe held focus) reclaim keyboard focus for the game iframe.
    reclaimFocus() {
      if (typeof window !== "undefined" && window.focus) window.focus();
    },
  };

  global.Poki = Poki;
})(window);

// ===== js/input.js =====
// input.js - keyboard state by keyCode (matches AS3 Input.isKeyDown usage) plus
// virtual buttons for the on-screen touch controls. The game asks for ACTIONS
// (brake / faster / restart); each action is satisfied by either a physical key
// or a held virtual button, so touch and keyboard drive the game identically.
(function (global) {
  "use strict";
  const down = {};
  // Virtual (on-screen button) action state, set by main.js pointer handlers.
  const virtual = { brake: false, faster: false };

  window.addEventListener("keydown", (e) => {
    down[e.keyCode] = true;
    // Stop the page from scrolling/zooming on the keys the game owns.
    if ([32, 37, 38, 39, 40].includes(e.keyCode)) e.preventDefault();
  });
  window.addEventListener("keyup", (e) => { down[e.keyCode] = false; });

  global.Input = {
    isKeyDown(code) { return !!down[code]; },
    // Held controls combine physical keys with the on-screen buttons.
    brake() { return virtual.brake || !!down[65] || !!down[37]; },   // A / Left
    faster() { return virtual.faster || !!down[68] || !!down[39]; }, // D / Right
    setVirtual(action, isDown) {
      if (action in virtual) virtual[action] = !!isDown;
    },
    clear() {
      for (const k in down) down[k] = false;
      virtual.brake = virtual.faster = false;
    },
  };
})(window);

// ===== js/assets.js =====
// assets.js - image, audio and font loading.
(function (global) {
  "use strict";

  const IMAGES = [
    "baby_arm_lower", "baby_arm_lower_lft", "baby_arm_lower_zombie", "baby_arm_upper",
    "baby_body", "baby_body1", "baby_body2", "baby_body3", "baby_head", "baby_head_zombie",
    "baby_leg_lower", "baby_leg_upper", "bg_bush", "bg_cloud", "bg_factory", "bg_grass",
    "bg_hospital", "bg_house", "bg_moon", "bg_mountain", "bg_office", "bg_pylon", "bg_tree",
    "obj_needle", "obj_stop_sign", "pram_body", "pram_chassis", "pram_handle", "pram_hood",
    "pram_wheel", "ui_mute_off", "ui_mute_on", "ui_title", "ui_titlescreen",
  ];
  const SOUNDS = ["giggle1", "giggle2", "giggle3", "babyBrains", "bounce", "doing", "click1", "click2", "needle", "tune1"];

  const imgs = {}, snds = {};

  const Assets = {
    img(name) {
      const im = imgs[name];
      if (!im) throw new Error("missing image: " + name);
      return im;
    },
    load(onProgress) {
      // Loading completion is gated on IMAGES + the font only. Audio is kicked off in
      // parallel but NOT awaited: waiting on `canplaythrough` is flaky (some browsers
      // never fire it until a user gesture) and the music is multi-MB, so blocking the
      // loading screen on it gave a long, unreliable wait. The clips keep buffering and
      // play() resolves once ready; the game starts the instant the art is in.
      let total = IMAGES.length + 1, done = 0;
      const tick = () => { done++; if (onProgress) onProgress(done, total); };
      return new Promise((resolve, reject) => {
        let pending = total;
        const settle = () => { if (--pending <= 0) resolve(); };
        IMAGES.forEach((n) => {
          const im = new Image();
          im.onload = () => { tick(); settle(); };
          im.onerror = () => reject(new Error("failed image " + n));
          im.src = "assets/grfx/" + n + ".png";
          imgs[n] = im;
        });
        // font
        const ff = new FontFace("Hobo", "url(assets/fonts/hobo.woff2) format('woff2'), url(assets/fonts/hobo.ttf) format('truetype')");
        ff.load().then((f) => { document.fonts.add(f); tick(); settle(); })
          .catch(() => { console.warn("font failed"); tick(); settle(); });
        // audio: fire-and-forget, buffers in the background.
        SOUNDS.forEach((n) => {
          const a = new Audio();
          a.preload = "auto";
          a.onerror = () => console.warn("audio missing", n);
          a.src = "assets/audio/" + n + ".ogg";
          snds[n] = a;
        });
      });
    },
    sound(name) { return snds[name]; },
  };

  // per-sound minimum replay gap in ms (mirrors game.as sfxGap, which throttled
  // sounds so e.g. the "doing" boing can't retrigger every frame while skidding).
  const GAP = { giggle1: 1621, giggle2: 1245, giggle3: 1445, babyBrains: 2448, click1: 69, click2: 84, needle: 425, bounce: 700, doing: 1149 };
  const nextOk = {};

  // simple sfx player (clones so sounds overlap)
  const Sound = {
    muted: false,        // user mute toggle (persisted)
    adMuted: false,      // forced mute for the duration of a Poki ad break
    musicChannel: null,
    play(name) {
      if (Sound.muted || Sound.adMuted) return;
      const a = snds[name];
      if (!a) return;
      const now = performance.now();
      if (now < (nextOk[name] || 0)) return;
      // all three giggles share one cooldown (as in the original)
      if (name.indexOf("giggle") === 0 &&
        (now < (nextOk.giggle1 || 0) || now < (nextOk.giggle2 || 0) || now < (nextOk.giggle3 || 0))) return;
      nextOk[name] = now + (GAP[name] || 0);
      try { const c = a.cloneNode(); c.volume = 1.0; c.play().catch(() => { }); } catch (e) { }
    },
    music(name, loop) {
      const a = snds[name];
      if (!a) return;
      if (Sound.musicChannel) { Sound.musicChannel.pause(); }
      a.loop = !!loop; a.currentTime = 0; a.volume = 0.6;
      Sound.musicChannel = a;
      Sound._sync();   // starts playing unless muted / ad-muted
    },
    stopMusic() { if (Sound.musicChannel) { Sound.musicChannel.pause(); Sound.musicChannel = null; } },
    setMuted(m) {
      Sound.muted = m;
      Store.set("zb_muted", m ? "1" : "0");
      Sound._sync();
    },
    // Poki requires game audio muted during ad playback; this is independent of the
    // user's own mute toggle so it never clobbers their preference.
    setAdMuted(m) {
      Sound.adMuted = m;
      Sound._sync();
    },
    _sync() {
      if (!Sound.musicChannel) return;
      if (Sound.muted || Sound.adMuted) Sound.musicChannel.pause();
      else Sound.musicChannel.play().catch(() => { });
    },
  };

  // Incognito-safe persistence: Poki games must work in incognito, where any
  // localStorage access can throw. Every call is wrapped so failure is a no-op.
  const Store = {
    get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch (e) { } },
  };

  // Restore the persisted mute preference (default: unmuted).
  Sound.muted = Store.get("zb_muted") === "1";

  global.Assets = Assets;
  global.Sound = Sound;
  global.Store = Store;
})(window);

// ===== js/ragdoll.js =====
// ragdoll.js - faithful port of src/ragdoll.as to planck.js + canvas.
// Box2D-Flash math is reproduced exactly; only the API names change.
(function (global) {
  "use strict";
  const pl = global.planck;
  const Vec2 = pl.Vec2;

  const S = 0.25;                 // scaleX/scaleY applied to every baby bitmap
  const overlap = 4.0 * S;        // joint overlap amount
  const DEG = Math.PI / 180;

  function img(name) { return Assets.img(name); }
  function W(name) { return img(name).naturalWidth * S; }
  function H(name) { return img(name).naturalHeight * S; }

  class Ragdoll {
    constructor(world, physScale, x, y) {
      this.world = world;
      this.ps = physScale;
      this.startX = x; this.startY = y;
      this.faceAlpha = 1.0;
      this.armCt = 1.0;

      // scaled bitmap dimensions (AS3 read bmp.width AFTER scaling)
      const faceW = W("baby_head"), faceH = H("baby_head");
      const b1W = W("baby_body1");
      const b2W = W("baby_body2");
      const b3W = W("baby_body3");
      const ulArmW = W("baby_arm_upper"), ulArmH = H("baby_arm_upper");
      const llArmW = W("baby_arm_lower_lft");
      const lrArmW = W("baby_arm_lower");
      const ulLegW = W("baby_leg_upper"), ulLegH = H("baby_leg_upper");
      const llLegLW = W("baby_leg_lower"), llLegLH = H("baby_leg_lower");

      const neck_y = faceH * 0.5 - 4 * overlap;
      const shoulder_y = neck_y + ulArmH * 0.5;
      const arm_y = shoulder_y;
      const shoulder_overlap = ulArmW * 0.3;
      const torso1_y = neck_y + 30 * S - overlap;
      const torso2_y = torso1_y + 30 * S - overlap;
      const hips_y = torso2_y + 30 * S * 0.5 - overlap;
      const hips_overlap = ulLegH * 0.2;
      const knees_y = hips_y - hips_overlap + ulLegH - overlap;
      this._dims = { faceW, faceH, b1W, b2W, b3W };

      const ps = physScale;
      const mk = (px, py, fix) => {
        const b = world.createBody({ type: "dynamic", position: Vec2(px / ps, py / ps) });
        b.createFixture(fix.shape, fix);
        b.setUserData("baby");
        return b;
      };
      const box = (hwPx, hhPx, extra) =>
        Object.assign({ shape: pl.Box(hwPx / ps, hhPx / ps), userData: "baby" }, extra);

      // --- Lower legs (group -1, dense) ---
      let f = { density: 10.0, friction: 0.4, restitution: 0.01, filterGroupIndex: -1 };
      this.lowerLegL = mk(x - b1W * 0.5 + llLegLW * 0.5, y + knees_y + llLegLH * 0.5 - overlap,
        box(llLegLW * 0.5, llLegLH * 0.5, f));
      this.lowerLegR = mk(x + b1W * 0.5 - llLegLW * 0.5, y + knees_y + llLegLH * 0.5 - overlap,
        box(W("baby_leg_lower") * 0.5, H("baby_leg_lower") * 0.5, f));

      // --- Upper legs (group -2) ---
      f = { density: 1.0, friction: 0.4, restitution: 0.01, filterGroupIndex: -2 };
      this.upperLegL = mk(x - b1W * 0.5 + ulLegW * 0.5, y + hips_y - hips_overlap + ulLegH * 0.5,
        box(ulLegW * 0.5, ulLegH * 0.5, f));
      this.upperLegR = mk(x + b1W * 0.5 - ulLegW * 0.5, y + hips_y - hips_overlap + ulLegH * 0.5,
        box(ulLegW * 0.5, ulLegH * 0.5, f));

      // --- Torsos / arms / head ---
      // NB: the AS3 reuses one fixtureDef and never resets groupIndex after the
      // upper legs, so every part from here on stays in group -2 (they do not
      // collide with each other). That is what makes the ragdoll floppy.
      f = { density: 1.0, friction: 0.4, restitution: 0.01, filterGroupIndex: -2 };
      this.torso1 = mk(x, y + neck_y + 30 * S * 0.5, box(b1W * 0.5, 30 * S * 0.5, f));
      this.torso2 = mk(x, y + neck_y + 30 * S - overlap + 30 * S * 0.5 - overlap, box(b2W * 0.5, 30 * S * 0.5, f));
      this.torso3 = mk(x, y + neck_y + 30 * S - overlap + 30 * S - overlap + 30 * S * 0.5 - overlap, box(b3W * 0.5, 30 * S * 0.5, f));

      // --- Upper arms ---
      this.upperArmL = mk(x - b1W * 0.5 + shoulder_overlap - ulArmW * 0.5, y + shoulder_y, box(ulArmW * 0.5, ulArmH * 0.5, f));
      this.upperArmR = mk(x + b1W * 0.5 - shoulder_overlap + ulArmW * 0.5, y + shoulder_y, box(ulArmW * 0.5, ulArmH * 0.5, f));

      // --- Lower arms ---
      this.lowerArmL = mk(x - b1W * 0.5 + shoulder_overlap - ulArmW + overlap - llArmW * 0.5, y + shoulder_y, box(llArmW * 0.5, H("baby_arm_lower_lft") * 0.5, f));
      this.lowerArmR = mk(x + b1W * 0.5 - shoulder_overlap + ulArmW - overlap + lrArmW * 0.5, y + shoulder_y, box(lrArmW * 0.5, H("baby_arm_lower") * 0.5, f));

      // --- Head ---
      const headR = (faceW + faceH) * 0.25;
      this.head = world.createBody({ type: "dynamic", position: Vec2(x / ps, y / ps) });
      this.head.createFixture(pl.Circle(headR / ps), { density: 1.0, friction: 0.4, restitution: 0.01, filterGroupIndex: -2, userData: "baby" });
      this.head.setUserData("baby");

      // --- Joints ---
      const joint = (a, b, anchorPx, lo, hi) => {
        world.createJoint(pl.RevoluteJoint(
          { enableLimit: true, lowerAngle: lo * DEG, upperAngle: hi * DEG },
          a, b, Vec2(anchorPx.x / ps, anchorPx.y / ps)));
      };
      joint(this.torso1, this.head, { x: x, y: y + neck_y }, -15, 15);
      joint(this.torso1, this.upperArmL, { x: x - b1W * 0.5 + overlap, y: y + shoulder_y }, -85, 20);
      joint(this.torso1, this.upperArmR, { x: x + b1W * 0.5 - overlap, y: y + shoulder_y }, -20, 85);
      joint(this.upperArmL, this.lowerArmL, { x: x - b1W * 0.5 + overlap - ulArmW + overlap, y: y + shoulder_y }, -45, 45);
      joint(this.upperArmR, this.lowerArmR, { x: x + b1W * 0.5 - overlap + ulArmW - overlap, y: y + shoulder_y }, -45, 45);
      joint(this.torso1, this.torso2, { x: x, y: y + torso1_y }, -5, 5);
      joint(this.torso2, this.torso3, { x: x, y: y + torso2_y }, -5, 5);
      joint(this.torso3, this.upperLegL, { x: x - b3W * 0.5 + ulLegW * 0.5, y: y + hips_y }, -25, 45);
      joint(this.torso3, this.upperLegR, { x: x + b3W * 0.5 - ulLegW * 0.5, y: y + hips_y }, -45, 25);
      joint(this.upperLegL, this.lowerLegL, { x: x - b3W * 0.5 + ulLegW * 0.5, y: y + knees_y }, -25, 115);
      joint(this.upperLegR, this.lowerLegR, { x: x + b3W * 0.5 - ulLegW * 0.5, y: y + knees_y }, -115, 25);
    }

    getLinearVelocity() { return this.head.getLinearVelocity(); }
    getPosition() { return this.head.getPosition(); }
    getBaby() { return this.head; }
    getX() { return this.head.getPosition().x * this.ps; }

    fadeFaceArms(amount) {
      this.faceAlpha = amount;
      this.armCt = amount * 0.5 + 0.5;
    }

    // world-space AABB of the head (for needle collisions)
    headBounds() {
      const p = this.head.getPosition();
      const r = this._dims.faceW * 0.5;
      return { x: p.x * this.ps - r, y: p.y * this.ps - r, w: r * 2, h: r * 2 };
    }

    _drawPart(ctx, body, name) {
      const p = body.getPosition();
      ctx.save();
      ctx.translate(p.x * this.ps, p.y * this.ps);
      ctx.rotate(body.getAngle());
      const im = img(name);
      const w = im.naturalWidth * S, h = im.naturalHeight * S;
      ctx.drawImage(im, -w * 0.5, -h * 0.5, w, h);
      ctx.restore();
    }

    draw(ctx) {
      // z-order matches the AS3 addChild sequence
      this._drawPart(ctx, this.lowerLegL, "baby_leg_lower");
      this._drawPart(ctx, this.lowerLegR, "baby_leg_lower");
      this._drawPart(ctx, this.upperLegL, "baby_leg_upper");
      this._drawPart(ctx, this.upperLegR, "baby_leg_upper");
      this._drawPart(ctx, this.torso3, "baby_body3");
      this._drawPart(ctx, this.torso2, "baby_body2");
      this._drawPart(ctx, this.torso1, "baby_body1");
      this._drawPart(ctx, this.upperArmL, "baby_arm_upper");
      this._drawPart(ctx, this.upperArmR, "baby_arm_upper");
      this._drawPart(ctx, this.lowerArmL, "baby_arm_lower_lft");
      this._drawPart(ctx, this.lowerArmR, "baby_arm_lower");
      // head: zombie behind, normal face fading on top
      this._drawPart(ctx, this.head, "baby_head_zombie");
      if (this.faceAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha = this.faceAlpha;
        this._drawPart(ctx, this.head, "baby_head");
        ctx.restore();
      }
    }
  }

  global.Ragdoll = Ragdoll;
})(window);

// ===== js/physics.js =====
// physics.js - port of src/Physics.as (the actual game) to planck.js + canvas.
(function (global) {
  "use strict";
  const pl = global.planck;
  const Vec2 = pl.Vec2;

  // Design height is locked at 480; the design WIDTH flexes with the window aspect
  // ratio so the canvas is filled edge-to-edge (no letterbox). main.js owns View and
  // updates it on every resize; screen-space drawing reads View.w / View.h live.
  const View = global.View || (global.View = { w: 640, h: 480, scale: 1, dpr: 1 });
  // Fixed DESIGN reference (the original game was authored at 640x480). World/level
  // generation and the gameplay triggers tuned to it stay on these constants; only
  // SCREEN-SPACE drawing (camera framing, background, HUD) reads the live View.
  const GW = 640, GH = 480;
  const PS = 30;                       // physics scale (px per metre)
  const TS = 1 / 30, VIT = 15, PIT = 15;
  const BABY_FELL_DELAY = 60, STOP_SIGN_WIDE = 48;
  const pramStartX = 150, pramStartY = 70;
  const startX = pramStartX + 25, startY = pramStartY - 70;
  const pramWide = 50, pramHigh = 8, pramWheelHigh = 20;
  const frontWheelSize = 16, backWheelSize = 24, wheelOffsetX = 32;
  const frontWheelHigh = pramWheelHigh + (backWheelSize - frontWheelSize) / 2;

  // persistent across restarts (matches AS3 static vars). The best distance also
  // persists across reloads via incognito-safe storage (Store wraps localStorage).
  let signPositions = [];
  let recordDistance = (() => {
    const v = global.Store ? parseFloat(global.Store.get("zb_record")) : NaN;
    return isFinite(v) ? v : 0;
  })();

  function img(n) { return Assets.img(n); }

  class Physics {
    constructor() {
      this.world = pl.World({ gravity: Vec2(0, 10) });
      this.world.on("begin-contact", (c) => this._contact(c, +1));
      this.world.on("end-contact", (c) => this._contact(c, -1));
      this.babyOnGround = 0;
      this.babyOnGroundCount = 0;
      this.firstContact = false;
      this.gameRunning = true;
      this.waitForReset = false;
      this.infectionSpread = 1.0;
      this.infectionSpeed = 0.25;
      this.runTime = 0; this.timeTaken = 0; this.timeBonus = 0;
      this.isRecord = false;
      this.nextGiggle = 1;
      this.dusts = [];
      this.needles = [];
      this.scenery = [];           // {img, x, y, z}
      this.grass = [];             // {x,y,angle,len}
      this.signs = [];             // {x,y}
      this.groundPts = [];
      this.endState = null;        // null | 'won' | 'lost'

      // camera (AS3 m_sprite.x/y)
      this.camX = 0; this.camY = GH;

      this._buildPram();
      this._buildWheels();
      this.baby = new Ragdoll(this.world, PS, startX, startY);
      this._buildHill(0.25);
      this._buildSigns();

      // snap camera to follow target so first frame looks right
      const p = this.baby.getPosition();
      this.camX = View.w * 0.33 - p.x * PS;
      this.camY = View.h * 0.5 - p.y * PS;
      // Don't show the empty space left of the first hill segment (wide screens only).
      const leftLimit = -this.groundPts[0].x;
      if (this.camX > leftLimit) this.camX = leftLimit;

      this.instrT = 0;             // instructions fade-in timer (frames)
      Sound.play("giggle3");
    }

    _contact(c, dir) {
      const a = String(c.getFixtureA().getUserData());
      const b = String(c.getFixtureB().getUserData());
      if (a !== "baby" && a !== "ground") return;
      if (b !== "baby" && b !== "ground") return;
      if (a !== b) this.babyOnGround += dir;
    }

    _buildPram() {
      const b = this.world.createBody({ type: "dynamic", position: Vec2(pramStartX / PS, pramStartY / PS) });
      b.createFixture(pl.Box(pramWide / PS, pramHigh / PS), { friction: 0.9, density: 1, restitution: 0.01, userData: "pram" });
      // rear wall
      b.createFixture(pl.Box(5 / PS, 10 / PS, Vec2(-(pramWide - 5) / PS, -(pramHigh + 10) / PS), 0), { friction: 0.9, density: 1, restitution: 0.01, userData: "pram" });
      // front wall
      b.createFixture(pl.Box(5 / PS, 20 / PS, Vec2((pramWide - 5) / PS, -(pramHigh + 20) / PS), 0), { friction: 0.9, density: 1, restitution: 0.01, userData: "pram" });
      this.pram = b;
    }

    _buildWheels() {
      const front = this.world.createBody({ type: "dynamic", position: Vec2((pramStartX + wheelOffsetX) / PS, (pramStartY + frontWheelHigh) / PS) });
      front.createFixture(pl.Circle(frontWheelSize / PS), { friction: 0.9, density: 30, restitution: 0.2, userData: "front wheel" });
      const rear = this.world.createBody({ type: "dynamic", position: Vec2((pramStartX - wheelOffsetX) / PS, (pramStartY + pramWheelHigh) / PS) });
      rear.createFixture(pl.Circle(backWheelSize / PS), { friction: 0.9, density: 30, restitution: 0.2, userData: "back wheel" });
      this.frontWheel = front; this.rearWheel = rear;
      this.world.createJoint(pl.RevoluteJoint({}, this.pram, front, front.getPosition()));
      this.world.createJoint(pl.RevoluteJoint({}, this.pram, rear, rear.getPosition()));
    }

    _buildHill(steepness) {
      let lastRamp = 0.0;
      const rampGap = GW * 5;
      let nextNeedle = GW, nextNeedleDistance = GW * 3;
      let x1 = -80, y1 = 100, x2, y2;

      const pts = this.groundPts;
      pts.push({ x: x1, y: y1 });
      do {
        if (x1 < lastRamp + rampGap) {
          x2 = x1 + Math.random() * 128 + 64;
          y2 = y1 + (Math.random() * 128 + 64) * steepness;
        } else {
          x2 = x1 + Math.random() * 32 + 128;
          y2 = y1 - 10;
          lastRamp = x1;
          steepness += Math.random() * 0.5;
        }
        pts.push({ x: x2, y: y2 });

        nextNeedle -= x2 - x1;
        if (nextNeedle <= 0) {
          const im = img("obj_needle");
          this.needles.push({ x: x2, y: y2 - im.naturalHeight * 0.5 - Math.random() * 80, rot: Math.random() * 360 - 180, s: 0.5, visible: true });
          nextNeedle += nextNeedleDistance;
          nextNeedleDistance = Math.min(nextNeedleDistance + GW / 3, GW * 8);
        }

        const angle = Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI;
        this.grass.push({ x: x1, y: y1 - 12, angle, len: Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2) * 1.1 });

        if (x2 < 45000) steepness += Math.random() - 0.75; else steepness -= 0.1;
        if (steepness < 0.15) steepness = 0.15;
        if (steepness > 1.50) steepness = 1.50;

        x1 = x2; y1 = y2;
      } while (x2 < 50000);

      // static collision chain along the surface
      const ground = this.world.createBody();
      const verts = pts.map(p => Vec2(p.x / PS, p.y / PS));
      ground.createFixture(pl.Chain(verts, false), { friction: 0.9, restitution: 0.1, userData: "ground" });

      this._placeScenery();
    }

    _findGround(x) {
      const pts = this.groundPts;
      for (let i = 1; i < pts.length; i++) {
        if (x < pts[i].x) {
          const dx = pts[i].x - pts[i - 1].x, dy = pts[i].y - pts[i - 1].y;
          return pts[i - 1].y + (x - pts[i - 1].x) * dy / dx;
        }
      }
      return NaN;
    }

    _placeScenery() {
      const pts = this.groundPts;
      const sw = (n) => img(n).naturalWidth, sh = (n) => img(n).naturalHeight;
      const houseOffset = 42, officeOffset = 42, factoryOffset = 42, hospitalOffset = 42;
      const pylonOffset = 377, pylonWidth = 156, treeTrunkWidth = 156, treeTrunkOffset = 109;
      let next = 0;
      const add = (n, x, y, z) => this.scenery.push({ img: img(n), x, y, z });

      for (let i = 0; i < pts.length - 2; i++) {
        const lx = pts[i].x;
        if (lx > 49000 && lx <= 49000 + (pts[i + 1].x - pts[i].x)) {
          // place hospital once near the foot
        }
        if (lx > 49000 && !this._hospitalPlaced) {
          this._hospitalPlaced = true;
          const w = sw("bg_hospital"), h = sh("bg_hospital");
          const x = 49900 - w;
          add("bg_hospital", x, this._findGround(x + w) - h + hospitalOffset * 0.5, -10);
          next = lx + w + 50;
          continue;
        }
        if (lx <= next) continue;
        const dx = pts[i + 1].x - lx, dy = pts[i + 1].y - pts[i].y, steep = dy / dx;
        const dx2 = pts[i + 2].x - pts[i + 1].x, dy2 = pts[i + 2].y - pts[i + 1].y, steep2 = dy2 / dx2;
        const flat = steep < 0.15, flat2 = steep2 < 0.15;
        let placed = false, w, h;
        const tryBuild = (n, off) => {
          w = sw(n); h = sh(n);
          add(n, lx, this._findGround(lx + w) - h + off * 0.5, -10);
          next = lx + w + 50; placed = true;
        };
        if (Math.random() < 0.20 && ((flat && dx > sw("bg_house") / 2) || (flat && flat2 && dx + dx2 > sw("bg_house") / 2))) tryBuild("bg_house", houseOffset);
        else if (Math.random() < 0.30 && ((flat && dx > sw("bg_office") / 2) || (flat && flat2 && dx + dx2 > sw("bg_office") / 2))) tryBuild("bg_office", officeOffset);
        else if (Math.random() < 0.45 && ((flat && dx > sw("bg_factory") / 2) || (flat && flat2 && dx + dx2 > sw("bg_factory") / 2))) tryBuild("bg_factory", factoryOffset);
        else if (Math.random() < 0.25 && ((steep < 0.18 && dx > pylonWidth / 2) || (steep < 0.18 && steep2 < 0.18 && dx + dx2 > pylonWidth / 2))) {
          w = sw("bg_pylon"); h = sh("bg_pylon");
          add("bg_pylon", lx - pylonOffset, this._findGround(lx + treeTrunkWidth) - h, -10); next = lx + w + 50; placed = true;
        }
        else if (steep < 0.2 && dx > treeTrunkWidth && Math.random() < 0.33) {
          w = sw("bg_tree"); h = sh("bg_tree");
          add("bg_tree", lx - treeTrunkOffset, this._findGround(lx + treeTrunkWidth) - h, -10); next = lx + w + 50; placed = true;
        }
        else if (steep < 0.2 && dx > treeTrunkWidth && Math.random() < 0.5) {
          w = sw("bg_bush"); h = sh("bg_bush");
          add("bg_bush", lx - treeTrunkOffset, this._findGround(lx + treeTrunkWidth) - h, -10); next = lx + w + 50; placed = true;
        }
        else if (Math.random() < 0.05) { w = sw("bg_mountain"); h = sh("bg_mountain"); add("bg_mountain", lx, this._findGround(lx + w) - h + houseOffset * 0.5, -20); next = lx + w + 100; placed = true; }
        else if (Math.random() < 0.07) { w = sw("bg_cloud"); h = sh("bg_cloud"); add("bg_cloud", lx, this._findGround(lx + w) - h - 200 - 200 * Math.random(), -30); next = lx + w + 50; placed = true; }
      }
      this.scenery.sort((a, b) => a.z - b.z);
    }

    _buildSigns() {
      for (const x of signPositions)
        this.signs.push({ x, y: this._findGround(x) - img("obj_stop_sign").naturalHeight * (STOP_SIGN_WIDE / img("obj_stop_sign").naturalWidth) });
    }

    update() {
      if (Input.isKeyDown(82)) { this.requestRestart = true; return; }   // R
      if (this.waitForReset) { this._endTick(); return; }

      // dust lifetimes
      for (let d = this.dusts.length - 1; d >= 0; d--) {
        this.dusts[d].life--; this.dusts[d].x += this.dusts[d].vx;
        if (this.dusts[d].life <= 0) this.dusts.splice(d, 1);
      }

      if (this.gameRunning) {
        this.runTime++;
        this.world.step(TS, VIT, PIT);

        const v = this.baby.getLinearVelocity();
        this.infectionSpread = Math.min(this.infectionSpread + this.infectionSpeed, 100);
        this.baby.fadeFaceArms(1.0 - this.infectionSpread / 100);

        if (this.babyOnGround || this.infectionSpread >= 100) {
          if (v.x < 2.0 || this.infectionSpread >= 100) {
            if ((this.babyOnGroundCount += 2) > BABY_FELL_DELAY) {
              const sx = this.baby.getX();
              this.signs.push({ x: sx, y: this._findGround(sx) - img("obj_stop_sign").naturalHeight * (STOP_SIGN_WIDE / img("obj_stop_sign").naturalWidth) });
              signPositions.push(sx);
              Sound.play("bounce");
              this.gameRunning = false;
              return;
            }
          } else if ((!this.firstContact && this.babyOnGround) || (this.babyOnGround && v.length() > 15.0)) {
            this.firstContact = true; Sound.play("doing");
          }
        } else {
          if (--this.babyOnGroundCount < 0) {
            this.babyOnGroundCount = 0;
            if (Math.random() < 0.0075) {
              Sound.play("giggle" + this.nextGiggle++);
              if (this.nextGiggle > 3) this.nextGiggle = 1;
            }
          }
        }

        // camera follows baby. In portrait the view is tighter, so follow more
        // closely (less lag) to keep the pram from drifting to the screen edge.
        const p = this.baby.getPosition();
        const lag = View.w < View.h ? 4 : 8;
        const cx = View.w * 0.33 - p.x * PS, cy = View.h * 0.5 - p.y * PS;
        this.camX += (cx - this.camX) / lag;
        this.camY += (cy - this.camY) / lag;
        // Don't show the empty space left of the first hill segment (wide screens only;
        // inactive once the pram has rolled right, where camX is far negative).
        const leftLimit = -this.groundPts[0].x;
        if (this.camX > leftLimit) this.camX = leftLimit;
        if (this.camX < -48200) {
          if (this.infectionSpread >= 99 - this.infectionSpeed) this.infectionSpeed = 0;
          if (this.camX < -50000 + GW) {
            this.camX = -50000 + GW; this.gameRunning = false;
            if (this.timeTaken === 0) this.timeTaken = this.runTime;
          } else {
            if (v.x > 8.0) this.rearWheel.applyLinearImpulse(Vec2(-48, 0), Vec2(0, 0), true);
            else if (v.x < 4.0) this.frontWheel.applyLinearImpulse(Vec2(16, 0), Vec2(0, 0), true);
          }
        }

        // controls (keyboard OR on-screen touch buttons, via Input action helpers)
        const vel = this.pram.getLinearVelocity();
        if (Input.brake() && vel.x > 4) {
          this.rearWheel.applyLinearImpulse(Vec2(-24, 0), Vec2(0, 0), true);
          if ((this.runTime & 3) === 0) this._dust(this.frontWheel, 8, 0.25);
        }
        if (this.camX < 48000 && Input.faster()) {
          this.frontWheel.applyLinearImpulse(Vec2(16, 0), Vec2(0, 0), true);
          if ((this.runTime & 3) === 0) this._dust(this.rearWheel, -4, -0.25);
        }

        // needle pickups
        const hb = this.baby.headBounds();
        const pramAabb = this._pramAabb();
        for (const n of this.needles) {
          if (!n.visible) continue;
          const nw = img("obj_needle").naturalWidth * n.s, nh = img("obj_needle").naturalHeight * n.s;
          const nb = { x: n.x - nw / 2, y: n.y - nh / 2, w: nw, h: nh };
          if (this._overlap(hb, nb) || this._overlap(pramAabb, nb)) {
            n.visible = false; this.infectionSpread = 0.0; Sound.play("needle");
          }
        }

        // instructions fade in over the first ~1s, then linger
        if (this.instrT < 240) this.instrT++;

        if (this.camX <= -48000) this._maybeWinSetup();
      } else {
        this._loseOrWinProgress();
      }
    }

    _maybeWinSetup() {}

    _loseOrWinProgress() {
      // after gameRunning stops: either reached hospital (win) or convert to zombaby (lose)
      if (this.camX <= -49990 + GW) {
        this.infectionSpeed = 0;
        this.infectionSpread = Math.max(this.infectionSpread - 0.5, 0);
        this.baby.fadeFaceArms(1.0 - this.infectionSpread / 100);
        if (this.infectionSpread <= 0 && !this.waitForReset) {
          this.timeBonus = Math.max(5000 - this.timeTaken, 0) / 10;
          this.endState = "won";
          this._finishScore();
          Sound.play("giggle3");
          this.waitForReset = true;
        }
      } else {
        this.infectionSpread = Math.min(this.infectionSpread + 2.0, 100);
        this.baby.fadeFaceArms(1.0 - this.infectionSpread / 100);
        if (this.infectionSpread >= 100 && !this.waitForReset) {
          this.endState = "lost";
          this._finishScore();
          Sound.play("babyBrains");
          this.waitForReset = true;
        }
      }
    }

    _finishScore() {
      const p = this.baby.getPosition();
      const dist = p.x + (this.endState === "won" ? this.timeBonus : 0);
      if (dist > recordDistance) {
        recordDistance = dist; this.isRecord = true;
        if (global.Store) global.Store.set("zb_record", String(Math.round(dist)));
      }
      this.finalDistance = dist;
    }

    _endTick() {
      // idle on the end screen; main.js handles click/key to restart
    }

    _dust(wheelBody, vx, off) {
      const p = wheelBody.getPosition();
      this.dusts.push({ x: p.x * PS, y: p.y * PS + 6, vx, life: 18, a: 1 });
    }

    _pramAabb() {
      const p = this.pram.getPosition();
      const w = pramWide * 1.6, h = 60;
      return { x: p.x * PS - w / 2, y: p.y * PS - h, w, h };
    }
    _overlap(a, b) { return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y; }

    // ---------------- rendering ----------------
    draw(ctx) {
      ctx.save();
      ctx.fillStyle = "#8CB5FF";
      ctx.fillRect(0, 0, View.w, View.h);
      ctx.translate(this.camX, this.camY);

      // scenery (back)
      for (const s of this.scenery) ctx.drawImage(s.img, s.x, s.y);

      // hill fill
      const pts = this.groundPts;
      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
      const last = pts[pts.length - 1];
      const FILL_BOTTOM = 200000;   // flat bottom well below the deepest point => soil always fills downward
      ctx.lineTo(last.x, FILL_BOTTOM);
      ctx.lineTo(pts[0].x, FILL_BOTTOM);
      ctx.closePath();
      ctx.fillStyle = "#402601";
      ctx.fill();

      // grass strips
      const grassImg = img("bg_grass");
      for (const g of this.grass) {
        ctx.save();
        ctx.translate(g.x, g.y);
        ctx.rotate(g.angle * Math.PI / 180);
        const scaleX = g.len / grassImg.naturalWidth;
        ctx.drawImage(grassImg, -12 * scaleX, -13, g.len, grassImg.naturalHeight);
        ctx.restore();
      }

      // signs
      const signImg = img("obj_stop_sign");
      const signScale = STOP_SIGN_WIDE / signImg.naturalWidth;
      for (const s of this.signs) ctx.drawImage(signImg, s.x, s.y, STOP_SIGN_WIDE, signImg.naturalHeight * signScale);

      // needles
      const ndl = img("obj_needle");
      for (const n of this.needles) {
        if (!n.visible) continue;
        ctx.save();
        ctx.translate(n.x, n.y);
        ctx.rotate(n.rot * Math.PI / 180);
        ctx.drawImage(ndl, -ndl.naturalWidth * n.s / 2, -ndl.naturalHeight * n.s / 2, ndl.naturalWidth * n.s, ndl.naturalHeight * n.s);
        ctx.restore();
      }

      // baby
      this.baby.draw(ctx);

      // pram skin (drawn over the baby)
      this._drawPram(ctx);

      // dust puffs
      for (const d of this.dusts) {
        ctx.save();
        ctx.globalAlpha = Math.max(0, d.life / 18) * 0.6;
        ctx.fillStyle = "#caa86a";
        ctx.beginPath(); ctx.arc(d.x, d.y, 6 + (18 - d.life), 0, Math.PI * 2); ctx.fill();
        ctx.restore();
      }
      ctx.restore();

      this._drawUI(ctx);
    }

    _drawPram(ctx) {
      const p = this.pram.getPosition();
      ctx.save();
      ctx.translate(p.x * PS, p.y * PS);
      ctx.rotate(this.pram.getAngle());
      ctx.scale(0.25, 0.25);
      const pramBmp = img("pram_body"), handle = img("pram_handle"), chassis = img("pram_chassis"), hood = img("pram_hood");
      const pbx = -pramBmp.naturalWidth * 0.5, pby = -pramBmp.naturalHeight * 0.7;
      // chassis (scaleY 0.8) behind body
      ctx.drawImage(chassis, -chassis.naturalWidth * 0.55, pby + chassis.naturalHeight * 0.5, chassis.naturalWidth, chassis.naturalHeight * 0.8);
      ctx.drawImage(pramBmp, pbx, pby);
      ctx.drawImage(handle, pbx - handle.naturalWidth * 0.8, pby - handle.naturalHeight * 0.65);
      ctx.drawImage(hood, 8, pby - hood.naturalHeight * 0.9);
      ctx.restore();

      this._drawWheel(ctx, this.frontWheel, 0.18);
      this._drawWheel(ctx, this.rearWheel, 0.25);
    }

    _drawWheel(ctx, body, scale) {
      const w = img("pram_wheel");
      const p = body.getPosition();
      ctx.save();
      ctx.translate(p.x * PS, p.y * PS);
      ctx.rotate(body.getAngle());
      ctx.scale(scale, scale);
      ctx.drawImage(w, -w.naturalWidth / 2, -w.naturalHeight / 2);
      ctx.restore();
    }

    _drawUI(ctx) {
      // on the end screen, draw only the focused panel (no HUD clutter behind it)
      if (this.endState && this.waitForReset) { this._drawEndScreen(ctx); return; }

      const W = View.w, H = View.h;
      const p = this.baby.getPosition();
      const v = this.baby.getLinearVelocity();
      ctx.textBaseline = "top";

      // All readouts are stacked along the TOP (the bottom corners are reserved for
      // the on-screen touch buttons, and bottom-centre for the control hint) so
      // nothing overlaps in either portrait or landscape. Fonts scale with the
      // dynamic design width so they fit a narrow phone in portrait.
      const infFont = Math.min(38, W * 0.085);
      const small = Math.min(24, Math.max(14, W * 0.05));
      const row1 = 6, row2 = row1 + infFont + 4, row3 = row2 + small + 2;

      // Infection: top-centre, the focal readout.
      ctx.font = infFont.toFixed(0) + "px Hobo, sans-serif";
      ctx.fillStyle = "#ff0000";
      ctx.textAlign = "center";
      const inf = Math.min(this.infectionSpread, 100).toFixed(0);
      ctx.fillText("Infection: " + inf + "%", W / 2, row1);

      // Distance / Record (row 2), Speed (row 3). The left column is indented past
      // the top-left mute button so it never overlaps it; Record is right-aligned.
      const leftX = 52;
      ctx.font = small.toFixed(0) + "px Hobo, sans-serif";
      ctx.fillStyle = "#ffffff";
      ctx.textAlign = "left";
      ctx.fillText("Distance: " + p.x.toFixed(0), leftX, row2);
      ctx.fillText("Speed: " + Math.max(v.x, 0).toFixed(1), leftX, row3);
      ctx.textAlign = "right";
      ctx.fillText("Record: " + recordDistance.toFixed(0), W - 16, row2);

      // Control hint, fading in at the start of a run. On touch it sits just ABOVE the
      // on-screen buttons (main.js publishes their top as BTN_TOP_Y); on desktop it
      // goes along the bottom. Either way it never overlaps the buttons.
      const a = Math.min(this.instrT / 60, 1) * (this.instrT < 220 ? 1 : Math.max(0, (240 - this.instrT) / 20));
      if (a > 0.01) {
        ctx.globalAlpha = a;
        ctx.fillStyle = "#ffff00";
        ctx.textAlign = "center";
        ctx.textBaseline = "alphabetic";
        ctx.font = small.toFixed(0) + "px Hobo, sans-serif";
        const hint = global.IS_TOUCH ? "BRAKE / GO - keep the Zombaby in the pram!"
                                     : "'A' = brake   'D' = faster - keep the Zombaby in the pram!";
        const hintY = (global.IS_TOUCH && global.BTN_TOP_Y) ? global.BTN_TOP_Y - 10 : H - 16;
        ctx.fillText(hint, W / 2, hintY);
        ctx.globalAlpha = 1;
        ctx.textBaseline = "top";
      }
    }

    _drawEndScreen(ctx) {
      const won = this.endState === "won";
      const W = View.w, H = View.h;
      const cx = W / 2;

      // dim the play field
      ctx.fillStyle = "rgba(0,0,0,0.45)";
      ctx.fillRect(0, 0, W, H);

      // centred panel (clamped so it fits a narrow portrait screen)
      const pw = Math.min(460, W - 32), ph = 300, px = cx - pw / 2, py = (H - ph) / 2;
      ctx.fillStyle = "rgba(18,20,30,0.88)";
      ctx.strokeStyle = won ? "#00e000" : "#ff3030";
      ctx.lineWidth = 4;
      ctx.beginPath();
      if (ctx.roundRect) ctx.roundRect(px, py, pw, ph, 18);
      else ctx.rect(px, py, pw, ph);
      ctx.fill(); ctx.stroke();

      ctx.textAlign = "center";
      // Each line shrinks to fit inside the panel so long values (e.g. a 4-digit
      // distance, or the desktop "Click or press R..." prompt) never overrun the edges
      // on a narrow portrait panel.
      const maxW = pw - 36;
      const line = (text, y, size, fill, stroke) => {
        let fs = size;
        ctx.font = fs + "px Hobo, sans-serif";
        const tw = ctx.measureText(text).width;
        if (tw > maxW) { fs = size * maxW / tw; ctx.font = fs + "px Hobo, sans-serif"; }
        ctx.textBaseline = "middle";
        if (stroke) { ctx.lineWidth = Math.max(3, fs / 10); ctx.strokeStyle = stroke; ctx.strokeText(text, cx, y); }
        ctx.fillStyle = fill; ctx.fillText(text, cx, y);
      };

      // title
      line(won ? "SAFE!" : "ZOMBABY!", py + 58, 64, won ? "#37e000" : "#ff2a2a", "#000000");

      // stats block (consistent rhythm)
      let y = py + 130;
      line("Distance  " + (this.finalDistance || 0).toFixed(0), y, 36, "#ffffff"); y += 44;
      if (won && this.timeBonus > 0) { line("Time Bonus  " + this.timeBonus.toFixed(0), y, 30, "#9fe89f"); y += 38; }
      line("Best  " + recordDistance.toFixed(0) + (this.isRecord ? "   NEW!" : ""), y, 30, this.isRecord ? "#ffd23f" : "#cfd2dc");

      // call to action, gently pulsing
      const pulse = 0.6 + 0.4 * Math.abs(Math.sin(performance.now() * 0.004));
      ctx.globalAlpha = pulse;
      line(global.IS_TOUCH ? "Tap to play again" : "Click or press R to play again",
        py + ph - 34, 26, "#ffe14d", "#5a4a00");
      ctx.globalAlpha = 1;
      ctx.textBaseline = "top";
    }
  }

  global.Physics = Physics;
  global.resetPersistentScores = function () { signPositions = []; recordDistance = 0; };
})(window);

// ===== js/main.js =====
// main.js - boot, title screen, fixed-step game loop, reactive fill layout,
// on-screen touch controls, pause, and Poki SDK integration.
(function (global) {
  "use strict";

  // Design height is LOCKED at 480; the design WIDTH flexes to the window aspect so
  // the canvas is filled edge-to-edge (Poki requires full-screen cover, no bars).
  const DESIGN_H = 480;
  // Visible world width in design units = View.h * aspect. On narrow (portrait)
  // screens that collapses to a slim slice and over-zooms the pram, so we guarantee
  // at least this much world width is shown - the design height grows to reach it,
  // which zooms back and reveals more sky/soil instead of magnifying the pram. Wide
  // (landscape/desktop) screens already exceed it, so their framing is unchanged.
  const MIN_VIEW_W = 380;
  const View = global.View || (global.View = { w: 640, h: DESIGN_H, scale: 1, dpr: 1 });

  let canvas, ctx, game = null, state = "loading";
  let paused = false;

  // ----- On-screen touch controls --------------------------------------------
  // touchMode follows the LAST INPUT ACTUALLY USED (seeded from the primary pointer):
  // a real touch turns the buttons on, a mouse/keyboard action turns them off. So a
  // touchscreen laptop driven with a mouse never shows phantom mobile buttons (a Poki
  // QA flag). Keyboard always drives the game regardless (input.js owns its keys).
  let touchMode = !!(global.matchMedia && global.matchMedia("(pointer: coarse)").matches);
  global.IS_TOUCH = touchMode;            // physics.js reads this to pick hint/label text
  let btn = { brake: null, faster: null, r: 44, m: 20 };
  const activePointers = new Map();       // pointerId -> 'brake' | 'faster'

  function setTouchMode(on) {
    if (touchMode === on) return;
    touchMode = on;
    global.IS_TOUCH = on;
    if (!on) {                            // switched to mouse/keyboard: release held buttons
      for (const action of activePointers.values()) Input.setVirtual(action, false);
      activePointers.clear();
    }
  }

  function layoutButtons() {
    const W = View.w, H = View.h;
    // Real-pixel thumb sizing, then convert to design units (divide by cssScale).
    const minDimCss = Math.min(global.innerWidth, global.innerHeight);
    const r = Math.max(52, Math.min(120, minDimCss * 0.14)) / View.scale / 2;
    const m = Math.max(16, minDimCss * 0.04) / View.scale;
    btn.r = r; btn.m = m;
    btn.brake = { cx: m + r, cy: H - m - r, label: "BRAKE" };
    btn.faster = { cx: W - m - r, cy: H - m - r, label: "GO" };
    global.BTN_TOP_Y = (H - m - r) - r;   // physics.js anchors the control hint above this
  }

  function buttonAt(dx, dy) {
    for (const key of ["brake", "faster"]) {
      const b = btn[key];
      if (!b) continue;
      // Generous square hit zone around the visible circle for fat-thumb tolerance.
      if (Math.abs(dx - b.cx) <= btn.r * 1.4 && Math.abs(dy - b.cy) <= btn.r * 1.6) return key;
    }
    return null;
  }

  function drawButtons() {
    if (!touchMode || state !== "playing" || !game || game.waitForReset || paused) return;
    for (const key of ["brake", "faster"]) {
      const b = btn[key];
      const held = [...activePointers.values()].includes(key);
      ctx.beginPath();
      ctx.arc(b.cx, b.cy, btn.r, 0, Math.PI * 2);
      ctx.fillStyle = held ? "rgba(255,255,255,0.40)" : "rgba(255,255,255,0.18)";
      ctx.fill();
      ctx.lineWidth = 3; ctx.strokeStyle = "rgba(255,255,255,0.7)"; ctx.stroke();
      ctx.fillStyle = "#ffffff";
      ctx.font = "bold " + Math.round(btn.r * 0.42) + "px Hobo, sans-serif";
      ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText(b.label, b.cx, b.cy);
    }
  }

  // ----- Reactive viewport ----------------------------------------------------
  function resize() {
    const dpr = global.devicePixelRatio || 1;
    const cssW = global.innerWidth, cssH = global.innerHeight;
    canvas.width = Math.floor(cssW * dpr);
    canvas.height = Math.floor(cssH * dpr);
    canvas.style.width = cssW + "px";
    canvas.style.height = cssH + "px";
    // Lock height (fill width) for wide screens; for tall/portrait screens grow the
    // design height so at least MIN_VIEW_W of world is visible (zoom back).
    const aspect = cssW / cssH;
    let H = DESIGN_H;
    if (H * aspect < MIN_VIEW_W) H = MIN_VIEW_W / aspect;
    const scale = cssH / H;
    View.scale = scale;
    View.w = cssW / scale;                // == H * aspect
    View.h = H;
    View.dpr = dpr;
    layoutButtons();
  }

  // Map a client (screen) point into design-space coordinates.
  function toDesign(clientX, clientY) {
    const r = canvas.getBoundingClientRect();
    return { x: (clientX - r.left) / View.scale, y: (clientY - r.top) / View.scale };
  }

  // ----- Title / mute ---------------------------------------------------------
  function drawTitle() {
    const W = View.w, H = View.h;
    const bg = Assets.img("ui_titlescreen");
    const portrait = W < H;
    // Sky-coloured backdrop behind the scene (matches the title art's sky).
    ctx.fillStyle = "#8CB5FF";
    ctx.fillRect(0, 0, W, H);
    let bw, bh, bx, by;
    if (portrait) {
      // Fit the whole scene to the WIDTH and sit it at the bottom, so the baby/pram
      // are fully visible (cover-fit crops them off the narrow sides) with sky above.
      const s = W / bg.naturalWidth;
      bw = W; bh = bg.naturalHeight * s; bx = 0; by = H - bh;
    } else {
      // Cover the whole canvas on wide screens.
      const s = Math.max(W / bg.naturalWidth, H / bg.naturalHeight);
      bw = bg.naturalWidth * s; bh = bg.naturalHeight * s; bx = (W - bw) / 2; by = (H - bh) / 2;
    }
    ctx.drawImage(bg, bx, by, bw, bh);

    // Logo near the top.
    const t = Assets.img("ui_title");
    const ts = Math.min(1, (W * 0.8) / t.naturalWidth);
    ctx.drawImage(t, W / 2 - t.naturalWidth * ts / 2, 28, t.naturalWidth * ts, t.naturalHeight * ts);

    // PLAY prompt: in the open sky above the scene in portrait; mid-screen in landscape.
    const playY = portrait ? Math.min(by - 46, H * 0.5) : H * 0.62;
    ctx.textAlign = "center";
    ctx.textBaseline = "alphabetic";
    ctx.font = "48px Hobo, sans-serif";
    ctx.fillStyle = "#ffff00";
    ctx.fillText("PLAY", W / 2, playY);
    ctx.font = "22px Hobo, sans-serif";
    const cta = touchMode ? "tap to start" : "click to start";
    ctx.lineWidth = 4; ctx.strokeStyle = "#7a1500";
    ctx.strokeText(cta, W / 2, playY + 40);
    ctx.fillStyle = "#ffffff";
    ctx.fillText(cta, W / 2, playY + 40);
  }

  // mute button (top-left). Sized in design units; hit-tested in design space.
  function muteBox() {
    const im = Assets.img("ui_mute_on");
    const scale = 0.5;
    return { x: 8, y: 8, w: im.naturalWidth * scale, h: im.naturalHeight * scale };
  }
  function drawMute() {
    // ui_mute_off shows when sound is ON, ui_mute_on when muted (original behaviour)
    const im = Assets.img(Sound.muted ? "ui_mute_on" : "ui_mute_off");
    const b = muteBox();
    ctx.drawImage(im, b.x, b.y, b.w, b.h);
  }

  // ----- Game flow ------------------------------------------------------------
  function startGame() {
    Input.clear();
    paused = false;
    game = new Physics();
    if (global.DEV_TOOLS) global.__game = game;   // test hook (stripped from release)
    state = "playing";
    Sound.music("tune1", true);
  }

  // Restart from an end screen: fire the interstitial FIRST (a no-op while ads are
  // off), then start the next run - so the ad never plays over live gameplay.
  let restarting = false;
  async function restartRun() {
    if (restarting) return;
    restarting = true;
    try { await Poki.commercialBreak(); startGame(); }
    finally { restarting = false; }
  }

  // First-input gesture: claim keyboard focus (Poki runs us in an iframe) and start.
  function onStartInput() {
    if (global.focus) global.focus();
    if (state === "title") { startGame(); return true; }
    if (state === "playing" && game && game.waitForReset) { restartRun(); return true; }
    return false;
  }

  // ----- Pointer input --------------------------------------------------------
  function onPointerDown(e) {
    e.preventDefault();
    setTouchMode(e.pointerType === "touch");

    // Mute toggle (works for mouse and touch). A mute click never also starts a run.
    const d = toDesign(e.clientX, e.clientY);
    if (state !== "loading") {
      const mb = muteBox();
      if (d.x >= mb.x && d.x <= mb.x + mb.w && d.y >= mb.y && d.y <= mb.y + mb.h) {
        Sound.setMuted(!Sound.muted); Sound.play("click1"); return;
      }
    }

    // Paused (touch has no ESC key): a tap anywhere resumes.
    if (paused) { paused = false; return; }

    // Title / end-screen: any tap/click starts or restarts.
    if (state === "title" || (state === "playing" && game && game.waitForReset)) {
      onStartInput(); return;
    }

    // In-play touch buttons (touch only; a mouse player drives via the keyboard).
    if (state === "playing" && touchMode && !paused) {
      const key = buttonAt(d.x, d.y);
      if (key) { activePointers.set(e.pointerId, key); Input.setVirtual(key, true); }
    }
  }
  function onPointerUp(e) {
    const key = activePointers.get(e.pointerId);
    if (key) Input.setVirtual(key, false);
    activePointers.delete(e.pointerId);
  }
  function onPointerMove(e) {
    if (e.pointerType === "mouse") setTouchMode(false);
    if (!activePointers.has(e.pointerId)) return;
    const prev = activePointers.get(e.pointerId);
    const d = toDesign(e.clientX, e.clientY);
    const key = buttonAt(d.x, d.y);
    if (key === prev) return;
    Input.setVirtual(prev, false);                 // slid off the button
    if (key) { Input.setVirtual(key, true); activePointers.set(e.pointerId, key); }
    else activePointers.delete(e.pointerId);
  }

  // ----- Keyboard -------------------------------------------------------------
  function onKeyDown(e) {
    // A physical game key means a keyboard player even if we guessed touch - drop
    // touch mode so the on-screen buttons hide.
    if ([65, 68, 37, 39, 82].includes(e.keyCode)) setTouchMode(false);

    // ESC / P: pause-resume during active play (Poki requirement). Folded into the
    // Poki playing state below, so the SDK stops on pause and restarts on resume.
    if (e.keyCode === 27 || e.keyCode === 80) {
      if (state === "playing" && game && !game.waitForReset) paused = !paused;
      return;
    }
    // Any other key starts the game from the title / acts as PLAY on the end screen.
    if (onStartInput()) return;
  }

  // ----- Poki gameplay tracking ----------------------------------------------
  let pokiPlaying = false;
  function syncPoki() {
    const playing = state === "playing" && game && !game.waitForReset && !paused;
    if (playing && !pokiPlaying) Poki.gameplayStart();
    else if (!playing && pokiPlaying) Poki.gameplayStop();
    pokiPlaying = playing;
  }

  // ----- Pause veil -----------------------------------------------------------
  function drawPauseVeil() {
    const W = View.w, H = View.h;
    ctx.fillStyle = "rgba(0,0,0,0.55)"; ctx.fillRect(0, 0, W, H);
    ctx.textAlign = "center"; ctx.textBaseline = "middle";
    ctx.fillStyle = "#ffffff"; ctx.font = "56px Hobo, sans-serif";
    ctx.fillText("PAUSED", W / 2, H / 2 - 20);
    ctx.font = "24px Hobo, sans-serif";
    ctx.fillText(touchMode ? "tap to resume" : "press ESC to resume", W / 2, H / 2 + 30);
  }

  // ----- Loop -----------------------------------------------------------------
  let acc = 0, last = 0;
  const STEP = 1000 / 30;
  function loop(ts) {
    requestAnimationFrame(loop);
    if (!last) last = ts;
    acc += ts - last; last = ts;
    if (acc > 250) acc = 250;                 // avoid spiral of death
    while (acc >= STEP) {
      // Freeze the sim while a restart is resolving (its ad break is in flight).
      if (state === "playing" && game && !paused && !restarting) {
        game.update();
        // R mid-run restart routes through the SAME ad flow as the end-screen
        // restart (commercialBreak first, a no-op while ads are off), rather than an
        // instant reset - so in the release build it never restarts over an ad.
        if (game.requestRestart) { restartRun(); break; }
      }
      acc -= STEP;
    }
    syncPoki();

    // Render: lock the base transform so all drawing is in design space at DPR.
    ctx.setTransform(View.scale * View.dpr, 0, 0, View.scale * View.dpr, 0, 0);
    if (state === "title") drawTitle();
    else if (state === "playing" && game) {
      game.draw(ctx);
      if (paused) drawPauseVeil();
      drawButtons();
    }
    if (state !== "loading") drawMute();
  }

  // ----- Boot -----------------------------------------------------------------
  global.addEventListener("load", async () => {
    canvas = document.getElementById("c");
    ctx = canvas.getContext("2d");
    resize();
    global.addEventListener("resize", resize);
    global.addEventListener("orientationchange", resize);

    canvas.addEventListener("pointerdown", onPointerDown);
    global.addEventListener("pointerup", onPointerUp);
    global.addEventListener("pointercancel", onPointerUp);
    global.addEventListener("pointermove", onPointerMove);
    global.addEventListener("keydown", onKeyDown);

    // Ads are live ONLY in the stripped release build (DEV_TOOLS folded false).
    Poki.adsEnabled = !global.DEV_TOOLS;
    Poki.audioSink = Sound;
    await Poki.init();

    const drawLoading = (txt) => {
      ctx.setTransform(View.scale * View.dpr, 0, 0, View.scale * View.dpr, 0, 0);
      ctx.fillStyle = "#000"; ctx.fillRect(0, 0, View.w, View.h);
      ctx.fillStyle = "#fff"; ctx.font = "20px sans-serif";
      ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText(txt, View.w / 2, View.h / 2);
    };
    drawLoading("Loading...");
    await Assets.load((d, t) => drawLoading("Loading " + d + "/" + t));

    Poki.gameLoadingFinished();
    state = "title";
    requestAnimationFrame(loop);
  });
})(window);
